// Without a forwarded ref, Slot must keep using the child's own ref directly (unwrapped).
// These tests lock that behavior in: they pass on both the pre-fix and post-fix Slot,
// proving the ref-composition change only affects the identity of the *composed* ref
// (i.e. only when a forwarded ref is present), not the child-ref pass-through path.
describe('Slot without a forwarded ref (child ref pass-through)', () => {
  afterEach(cleanup);

  it('calls the child ref once on mount, not on re-render, and with null on unmount', () => {
    const childRef = vi.fn();
    const { rerender, unmount } = render(
      <Slot>
        <button ref={childRef} type="button">
          hi
        </button>
      </Slot>,
    );
    const button = screen.getByRole('button');
    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenLastCalledWith(button);

    rerender(
      <Slot>
        <button ref={childRef} type="button">
          hi
        </button>
      </Slot>,
    );
    expect(childRef).toHaveBeenCalledTimes(1);

    unmount();
    expect(childRef).toHaveBeenCalledTimes(2);
    expect(childRef).toHaveBeenLastCalledWith(null);
  });

  it('keeps native re-attach semantics when the child ref identity changes', () => {
    const calls: (HTMLButtonElement | null)[] = [];

    const Parent = () => {
      const [tick, setTick] = React.useState(0);
      // A fresh identity on every render, as an inline `ref={(n) => ...}` would be.
      const childRef = (node: HTMLButtonElement | null) => {
        calls.push(node);
      };

      return (
        <React.Fragment>
          <Slot data-slot="">
            <button ref={childRef} type="button">
              slotted
            </button>
          </Slot>
          <button type="button" onClick={() => setTick((t) => t + 1)}>
            tick
          </button>
        </React.Fragment>
      );
    };

    render(<Parent />);
    fireEvent.click(screen.getByRole('button', { name: 'tick' }));
    const slotted = screen.getByRole('button', { name: 'slotted' });

    // Exactly what React does with the child's own ref: attach on mount, then
    // null + node whenever the ref identity changes. No extra wrapping.
    expect(calls).toEqual([slotted, null, slotted]);
  });
});

